    // ===== 1000题并入 30讲/36讲（题目区合并；进度仍按书分开） =====
    // 1000题基础篇并入基础30讲、强化篇并入强化36讲；零基础(ch85)变为「第0讲」。
    // 合并只影响浏览/题目区：30讲/36讲章节在原地追加 q1000Id(伴章)并生成合并 labels；
    // 1000题章节对象(ch67-133)保留作为数据源与统计单元(wb 不变)。
    // 进度按书分开的机制：合并章节的「自身部分」与「1000题部分」分别落到本章/伴章各自的存储键，
    // 由内存态 statuses[qBad/sBad/notes] 用合并索引承载，load/save 时按书拆开读写。
    (function merge1000IntoBooks() {
      var SHU1 = SHU1_CHAPTERS;
      var baseSubjectName = function (subj) { return String(subj).replace(/^(基础篇|强化篇)[-—]/, ''); };
      // 提取 short 前缀（"第N讲"/"第N章"）与描述部分
      function splitShort(short) {
        var m = /^(第\d+(?:讲|章)\s*)(.*)$/.exec(String(short));
        return m ? { prefix: m[1], desc: m[2] } : { prefix: '', desc: String(short) };
      }
      function joinShort(prefix, desc) { return (prefix + ' ' + desc).replace(/\s+/g, ' ').trim(); }

      // 1) 零基础 ch85 → 第0讲：改字段并移到 30讲·高数 最前（ch1 之前）
      var zeroIdx = -1;
      for (var z = 0; z < SHU1.length; z++) { if (SHU1[z].id === 'ch85') { zeroIdx = z; break; } }
      if (zeroIdx !== -1) {
        var zero = SHU1[zeroIdx];
        SHU1.splice(zeroIdx, 1);
        zero.wb = '基础30讲';
        zero.subj = '高数';
        zero.number = 0;
        zero.short = '第0讲 零基础';
        zero.name = '基础30讲 - 高数 - 第0讲 零基础';
        zero.statsWb = '1000题';          // 进度仍按 1000题 统计
        zero.statsSubj = '基础篇-高数';
        var ch1Idx = 0;
        for (var c = 0; c < SHU1.length; c++) { if (SHU1[c].id === 'ch1') { ch1Idx = c; break; } }
        SHU1.splice(ch1Idx, 0, zero);
      }

      // 3) 配对：按 (书, 学科) 分组后的顺序下标一一配对
      // base 侧（30讲/36讲）subj 即主学科名；1000题侧 subj 为 '基础篇-高数' 形式。
      // 基础30讲 分组的 base 侧排除第0讲（statsWb 已改 '1000题' 的第0讲只作展示、不参与配对）。
      function groupBase(book, subj) {
        return SHU1.filter(function (c) {
          return c.wb === book && c.subj === subj && c.total > 0 && !c.statsWb;
        });
      }
      function groupQ(book, subj) {
        return SHU1.filter(function (c) {
          return c.wb === book && c.subj === subj && c.total > 0;
        });
      }
      var books3 = ['基础30讲', '强化36讲'];
      var booksQ = ['1000题', '1000题'];
      var qPrefix = ['基础篇', '强化篇'];
      var mainSubjs = ['高数', '线代', '概率论'];
      for (var bIdx = 0; bIdx < books3.length; bIdx++) {
        var book3 = books3[bIdx];
        var bookQ = booksQ[bIdx];
        var qpfx = qPrefix[bIdx];
        for (var s = 0; s < mainSubjs.length; s++) {
          var ms = mainSubjs[s];
          var baseChs = groupBase(book3, ms);
          var qChs = groupQ(bookQ, qpfx + '-' + ms);
          for (var p = 0; p < baseChs.length && p < qChs.length; p++) {
            var bc = baseChs[p];
            var qc = qChs[p];
            bc.q1000Id = qc.id;

            // 章节名统一：只统一描述部分，前缀（第N讲/第N章）各自保留
            // 高数：描述以 1000题 为准；概率论：描述以 30讲/36讲 为准；线代两书一致
            var bs = splitShort(bc.short);
            var qs = splitShort(qc.short);
            if (ms === '高数') {
              // 高数：base 章节描述 ← 1000题 描述；1000题 short 不变
              bc.short = joinShort(bs.prefix, qs.desc);
              bc.name = bc.wb + ' - ' + bc.subj + ' - ' + bc.short;
            } else if (ms === '概率论') {
              // 概率论：1000题 章节描述 ← base 章节描述；base short 不变
              qc.short = joinShort(qs.prefix, bs.desc);
              qc.name = qc.wb + ' - ' + qc.subj + ' - ' + qc.short;
            }
            // 线代：两书目录名一致，不改

            // 合并 labels
            bc.ownTotal = bc.labels.length;
            bc.q1000Total = qc.total;
            bc.labels = bc.labels.concat(qc.labels);
            bc.total = bc.labels.length;
          }
        }
      }
    })();
    // 1000题保持独立，不再合并进 30讲/36讲。
    SHU1_CHAPTERS.forEach(function (chapter) {
      if (chapter.ownTotal) {
        chapter.labels = chapter.labels.slice(0, chapter.ownTotal);
        chapter.total = chapter.ownTotal;
        delete chapter.ownTotal;
        delete chapter.q1000Id;
        delete chapter.q1000Total;
      }
    });
    if (Array.isArray(window.LILIN880_CHAPTERS)) {
      window.LILIN880_CHAPTERS.forEach(function (chapter) { SHU1_CHAPTERS.push(chapter); });
    }
    // ===== 科目（subject）数据模型：数学 =====
    const SUBJECTS = [
      {
        id: 'shu1', name: '数学', storageSuffix: 's1', initChapterId: 'ch1', navCols: 5,
        partOrder: ['例题', '习题'],
        wbOrder: [
          { wb: '基础30讲', label: '基础30讲' },
          { wb: '强化36讲', label: '强化36讲' },
          { wb: '1000题', label: '1000题' },
          { wb: '李林880', label: '李林880' },
          { wb: '李范全书', label: '李范全书' }
        ],
        subjOrder: ['高数', '线代', '概率论'],
        classifyLabel: function (label) { return label.startsWith('例') ? '例题' : '习题'; },
        getImgPath: function (ch, label) {
          var index = ch.labels.indexOf(label);

          if (ch.fileBases && ch.fileBases[index]) {
            return '数一题库/' + ch.relPath + '/' + ch.fileBases[index];
          }

          var rawLabel = String(label || '');
          var is1000Question =
            ch.wb === '1000题' ||
            ch.statsWb === '1000题';

          var hasExamplePrefix = rawLabel.startsWith('例');
          var numberPart = hasExamplePrefix
            ? rawLabel.substring(1)
            : rawLabel;

          // 1000题仓库中的真实文件名使用 ex_ 前缀
          var prefix = is1000Question || hasExamplePrefix
            ? 'ex'
            : 'pb';

          return '数一题库/' +
            ch.relPath +
            '/' +
            prefix +
            '_' +
            numberPart;
        },
        chapters: SHU1_CHAPTERS
      },
    ]
    // 仅保留原项目已有的六本专业课（重构时不再附带额外题库）。
    const PROFESSIONAL_CHAPTERS = Array.isArray(window.PROFESSIONAL_CHAPTERS) ? window.PROFESSIONAL_CHAPTERS : [];
    const PROFESSIONAL_BOOKS = ['何子述课后刷题本', '吴大正课后刷题本', '奥本海姆课后刷题本', '杨晓非课后刷题本', '管致中课后刷题本', '郑君里课后刷题本'];
    SUBJECTS.splice(1, 1, {
      id: 'zhuanye', name: '专业课', desc: '原有专业课刷题本', storageSuffix: 'zhuanye',
      initChapterId: PROFESSIONAL_CHAPTERS[0] ? PROFESSIONAL_CHAPTERS[0].id : '', navCols: 5,
      partOrder: ['例题'],
      wbOrder: PROFESSIONAL_BOOKS.map(function (wb) { return { wb: wb, label: wb }; }),
      subjOrder: ['专业课'],
      classifyLabel: function () { return '例题'; },
      getImgPath: function (ch, label) {
        var index = ch.labels.indexOf(label);
        var base = ch.fileBases && ch.fileBases[index];
        return '专业题库/' + ch.relPath + '/' + (base || label);
      },
      chapters: PROFESSIONAL_CHAPTERS
    });

    if (typeof window !== 'undefined') {
      window.SUBJECTS = SUBJECTS;
    }
